 {"id": "PEDS-C27-047", "sec": "Lung function abnormalities", "page": 121, "q": "An FEV1/FVC ratio of less than 0.8 indicates airflow limitation in asthma.", "opts": ["True", "False"], "ans": 0, "exp": "True — airflow limitation: FEV1 ↓, FEV1/FVC ratio < 0.8 (Book p121)", "type": "tf"},
 {"id": "PEDS-C27-048", "sec": "Lung function abnormalities", "page": 121, "q": "A bronchodilator response in asthma is defined as FEV1 increasing by more than 15%.", "opts": ["True", "False"], "ans": 1, "exp": "False — bronchodilator response: FEV1 ↑ by > 12% (> 15% is the fall on exercise challenge). (Book p121)", "type": "tf"},
 {"type": "case", "sec": "Lung function abnormalities", "page": 121, "stem": "A 9-year-old with recurrent nocturnal wheeze undergoes spirometry: FEV1 is reduced with an FEV1/FVC ratio of 0.7. After 400 mcg inhaled salbutamol, FEV1 improves by 15%. Peak flow records over 2 weeks vary by 25% between morning and evening readings.", "q": "These lung function findings are —", "opts": ["Normal for age with no abnormality", "Diagnostic of reversible airflow obstruction (asthma)", "Suggestive of a fixed restrictive defect", "Diagnostic of bronchiolitis obliterans"], "ans": 1, "exp": "FEV1 ↓ with FEV1/FVC < 0.8 = airflow limitation; post-bronchodilator FEV1 ↑ > 12% = bronchodilator response; AM-to-PM variation > 20% = diurnal variation → reversible airflow obstruction of asthma. (Book p121)", "id": "PEDS-C27-049"},
 {"type": "odd", "sec": "Lung function abnormalities", "page": 121, "q": "Odd one out (parameters used to demonstrate asthma):", "opts": ["Rise in FEV1 by > 12% after bronchodilator", "AM to PM variation in PEF by > 20%", "Rise in FEV1 by > 12% after nebulised saline", "Fall in FEV1 by > 15% on exercise challenge"], "ans": 2, "exp": "Exercise fall > 15%, bronchodilator rise > 12% and diurnal variation > 20% are the described asthma parameters; SALINE is not a bronchodilator. (Book p121)", "id": "PEDS-C27-050"},
 {"id": "PEDS-C27-051", "sec": "Management of asthma", "page": 121, "q": "Asthma management in this chapter is based on ___ guidelines.", "opts": ["WHO-ARI", "CDC", "NICE paediatric", "GINA (Global Initiative Network for Asthma)"], "ans": 3, "exp": "Based on Global Initiative Network for Asthma (GINA) guidelines (Book p121)", "type": "fill"},
 {"id": "PEDS-C27-052", "sec": "Management of asthma", "page": 121, "q": "Broadly, management of asthma consists of —", "opts": ["Identification & elimination of exacerbating factors + pharmacotherapy", "Antibiotics + chest physiotherapy", "Oxygen therapy + antitussives alone", "Immunisation + nutrition alone"], "ans": 0, "exp": "Management → identification & elimination of exacerbating factors; pharmacotherapy (Book p121)", "type": "mcq"},
 {"id": "PEDS-C27-053", "sec": "Management of asthma", "page": 121, "q": "Pharmacotherapy of asthma is divided into ___ and ___ management.", "opts": ["inpatient; day-care", "long-term; acute exacerbations", "oral; injectable", "curative; palliative"], "ans": 1, "exp": "Pharmacotherapy → long-term management; acute exacerbations (Book p121)", "type": "fill"},
 {"id": "PEDS-C27-054", "sec": "Long-term management", "page": 121, "q": "Asthma in a child aged > 12 yr is —", "opts": ["Treated only with oral steroids", "Not treated until 18 yr", "Managed as in adults", "Managed with preschool protocols"], "ans": 2, "exp": "Age > 12 yr: managed as in adults (Book p121)", "type": "mcq"},
 {"id": "PEDS-C27-055", "sec": "Long-term management", "page": 121, "q": "Asthma in a child aged 6 to 11 yr is managed by ___ management.", "opts": ["single-drug", "as-needed only", "symptom-triggered only", "stepwise"], "ans": 3, "exp": "Age 6 to 11 yr: stepwise management (Book p121)", "type": "fill"},
 {"id": "PEDS-C27-056", "sec": "Long-term management", "page": 121, "q": "Reliever therapy in asthma is —", "opts": ["Short-acting β-agonist (SABA)", "Long-acting β-agonist", "Inhaled corticosteroid", "Leukotriene antagonist"], "ans": 0, "exp": "Reliever therapy → short-acting β-agonist (SABA) (SOS for sudden exacerbation of symptoms) (Book p121)", "type": "mcq"},
 {"id": "PEDS-C27-057", "sec": "Long-term management", "page": 121, "q": "SABA reliever therapy is used ___ (as needed) for sudden exacerbation of symptoms.", "opts": ["only after meals", "SOS (as needed)", "daily at bedtime", "weekly on fixed days"], "ans": 1, "exp": "Reliever therapy → SABA (SOS for sudden exacerbation of symptoms) (Book p121)", "type": "fill"},
 {"id": "PEDS-C27-058", "sec": "Stepwise management", "page": 121, "q": "Step I of asthma therapy applies when symptoms occur —", "opts": ["daily", "daily with night symptoms", "< 2/month", "> 2/month but not daily"], "ans": 2, "exp": "Step I: symptoms < 2/month (Book p121)", "type": "mcq"},
 {"id": "PEDS-C27-059", "sec": "Stepwise management", "page": 121, "q": "Controller therapy at Step I of asthma —", "opts": ["Daily medium dose ICS", "Daily high dose ICS + LABA", "Biological agents", "Whenever SABA taken → ICS low dose"], "ans": 3, "exp": "Step I: whenever SABA taken → ICS low dose (Book p121)", "type": "mcq"},
 {"id": "PEDS-C27-060", "sec": "Stepwise management", "page": 121, "q": "Step II applies when symptoms occur > 2/month and are not daily; the controller therapy is ___.", "opts": ["daily low dose ICS", "whenever SABA is taken", "daily medium dose ICS", "daily high dose ICS"], "ans": 0, "exp": "Step II: > 2/month; not daily → daily low dose ICS (Book p121)", "type": "fill"},
 {"id": "PEDS-C27-061", "sec": "Stepwise management", "page": 121, "q": "Step III is indicated by daily symptoms + night symptoms —", "opts": ["never", "≥ 1/week", "< 2/month", "≥ 1/month"], "ans": 1, "exp": "Step III: daily symptoms + night symptoms ≥ 1/week (Book p121)", "type": "mcq"},
 {"id": "PEDS-C27-062", "sec": "Stepwise management", "page": 121, "q": "Controller therapy at Step III of asthma —", "opts": ["Biological agents as last resort", "SABA alone as needed", "Daily low dose ICS + LABA OR daily medium dose ICS", "Daily high dose ICS + LABA"], "ans": 2, "exp": "Step III: daily low dose ICS + LABA OR daily medium dose ICS (Book p121)", "type": "mcq"},
 {"id": "PEDS-C27-063", "sec": "Stepwise management", "page": 121, "q": "Step IV is indicated by daily symptoms + night symptoms ≥ 1/week plus ___.", "opts": ["normal spirometry", "obesity", "allergic rhinitis", "low lung function"], "ans": 3, "exp": "Step IV: daily symptoms + night symptoms ≥ 1/wk + low lung function (Book p121)", "type": "fill"},
 {"id": "PEDS-C27-064", "sec": "Stepwise management", "page": 121, "q": "Controller therapy at Step IV of asthma —", "opts": ["Daily medium dose ICS + LABA OR high dose ICS", "Daily low dose ICS only", "Whenever SABA is taken → ICS low dose", "SABA alone"], "ans": 0, "exp": "Step IV: daily medium dose ICS + LABA OR high dose ICS (Book p121)", "type": "mcq"},
 {"id": "PEDS-C27-065", "sec": "Stepwise management", "page": 121, "q": "Step V applies to asthma —", "opts": ["Newly diagnosed preschool wheeze", "Uncontrolled on Step IV", "Controlled on Step III", "Symptoms < 2/month"], "ans": 1, "exp": "Step V: uncontrolled on Step IV (Book p121)", "type": "mcq"},
 {"id": "PEDS-C27-066", "sec": "Stepwise management", "page": 121, "q": "The last-resort therapy at Step V of asthma —", "opts": ["Theophylline", "Nebulised ipratropium", "Biological agents", "Oral prednisolone daily"], "ans": 2, "exp": "Step V: daily high dose ICS + LABA (+/−), biological agents (last resort) (Book p121)", "type": "mcq"},
 {"type": "match", "sec": "Stepwise management", "page": 121, "q": "Match Column A with Column B — select the correctly matched combination:", "pairs": [["Step I", "> 2/month, not daily → daily low dose ICS"], ["Step II", "Daily medium dose ICS + LABA OR high dose ICS"], ["Step III", "< 2/month → ICS low dose whenever SABA taken"], ["Step IV", "Daily low dose ICS + LABA OR daily medium dose ICS"]], "opts": ["A-1, B-3, C-2, D-4", "A-4, B-3, C-1, D-2", "A-4, B-1, C-3, D-2", "A-3, B-1, C-4, D-2"], "ans": 3, "exp": "Correct pairs: Step I→< 2/month → ICS low dose whenever SABA taken; Step II→> 2/month, not daily → daily low dose ICS; Step III→Daily low dose ICS + LABA OR daily medium dose ICS; Step IV→Daily medium dose ICS + LABA OR high dose ICS. (Book p121)", "id": "PEDS-C27-067"},
 {"type": "case", "sec": "Stepwise management", "page": 121, "stem": "A 9-year-old boy has daily wheezing with night symptoms twice a week. Spirometry shows low lung function. He is not controlled on Step III therapy.", "q": "He requires —", "opts": ["Daily medium dose ICS + LABA OR high dose ICS", "SABA as needed with low dose ICS only when taken", "Daily low dose ICS alone", "An oral antibiotic course with chest physiotherapy"], "ans": 0, "exp": "Daily symptoms + night symptoms ≥ 1/week + low lung function = Step IV therapy: daily medium dose ICS + LABA OR high dose ICS. (Book p121)", "id": "PEDS-C27-068"},
 {"id": "PEDS-C27-069", "sec": "Stepwise management", "page": 121, "q": "Biological agents are first-line controller therapy at Step III of asthma management.", "opts": ["True", "False"], "ans": 1, "exp": "False — biological agents are last-resort therapy at Step V (uncontrolled on Step IV). (Book p121)", "type": "tf"},
 {"id": "PEDS-C27-070", "sec": "Pharmacotherapy", "page": 121, "q": "SABA stands for ___.", "opts": ["Steroid and bronchodilator combination", "Selective anti-bronchospasm agent", "Short-acting β-agonist", "Slow-acting bronchodilator agent"], "ans": 2, "exp": "SABA: short acting β-agonist (Book p121)", "type": "fill"},
 {"id": "PEDS-C27-071", "sec": "Pharmacotherapy", "page": 121, "q": "LABA stands for long-acting β-agonist; the drug of this class mentioned is ___.", "opts": ["salbutamol", "terbutaline", "budesonide", "formoterol"], "ans": 3, "exp": "LABA: long acting β-agonist (formoterol) (Book p121)", "type": "fill"},
 {"id": "PEDS-C27-072", "sec": "Pharmacotherapy", "page": 121, "q": "LABA has a synergistic effect with steroids.", "opts": ["True", "False"], "ans": 0, "exp": "True — LABA: synergistic effect with steroid (Book p121)", "type": "tf"},
 {"id": "PEDS-C27-073", "sec": "Pharmacotherapy", "page": 121, "q": "The long-term benefit of LABA with ICS is —", "opts": ["Reduced growth velocity", "Steroid sparing effect", "Antibiotic sparing effect", "Bronchodilator tolerance"], "ans": 1, "exp": "LABA: synergistic effect with steroid; steroid sparing effect (long-term) (Book p121)", "type": "mcq"},
