 {"id": "PEDS-C27-078", "sec": "Pharmacotherapy", "page": 121, "q": "Biological agents used in asthma are ___.", "opts": ["Long-acting β-agonists", "Inhaled anticholinergics", "Immunomodulatory monoclonal antibodies", "Oral corticosteroids"], "ans": 2, "exp": "Biological agents: immunomodulatory monoclonal antibodies (Book p121)", "type": "mcq"},
 {"id": "PEDS-C27-079", "sec": "Pharmacotherapy", "page": 121, "q": "Omalizumab acts against —", "opts": ["IL5", "IL4 receptor", "TSLP", "IgE"], "ans": 3, "exp": "Omalizumab: anti-IgE (Book p121)", "type": "mcq"},
