 {"type": "match", "sec": "Pharmacotherapy", "page": 121, "q": "Match Column A with Column B — select the correctly matched combination:", "pairs": [["Omalizumab", "New drug (anti-TSLP)"], ["Mepolizumab", "Anti-IgE"], ["Dupilumab", "Anti-IL5"], ["Anti-TSLP", "Anti-IL4 receptor"]], "opts": ["A-3, B-2, C-1, D-4", "A-2, B-3, C-4, D-1", "A-4, B-1, C-3, D-2", "A-4, B-1, C-2, D-3"], "ans": 1, "exp": "Correct pairs: Omalizumab→Anti-IgE; Mepolizumab→Anti-IL5; Dupilumab→Anti-IL4 receptor; Anti-TSLP→New drug (anti-TSLP). (Book p121)", "id": "PEDS-C27-083"},
 {"type": "odd", "sec": "Pharmacotherapy", "page": 121, "q": "Odd one out (monoclonal antibody biological agents used in asthma):", "opts": ["Formoterol", "Omalizumab", "Mepolizumab", "Dupilumab"], "ans": 0, "exp": "Omalizumab/mepolizumab/dupilumab are immunomodulatory monoclonal antibodies; formoterol is a long-acting β-agonist (LABA). (Book p121)", "id": "PEDS-C27-084"},
 {"id": "PEDS-C27-085", "sec": "Pharmacotherapy", "page": 121, "q": "Medium dose budesonide (ICS) is 200 to 400 mcg.", "opts": ["True", "False"], "ans": 1, "exp": "False — 200–400 mcg is the LOW dose; medium dose is 400–800 mcg. (Book p121)", "type": "tf"},
 {"id": "PEDS-C27-086", "sec": "Age < 5 yr (preschool)", "page": 122, "q": "Age < 5 yr group with asthma is called the ___ group.", "opts": ["adolescent", "school-age", "preschool", "neonatal"], "ans": 2, "exp": "Age < 5 yr (preschool) (Book p122)", "type": "fill"},
 {"id": "PEDS-C27-087", "sec": "Age < 5 yr (preschool)", "page": 122, "q": "Asthma may resolve after 5 yr in some preschool patients.", "opts": ["True", "False"], "ans": 0, "exp": "True — asthma may resolve > 5 yr in some patients (Book p122)", "type": "tf"},
 {"id": "PEDS-C27-088", "sec": "Age < 5 yr (preschool)", "page": 122, "q": "Preschool wheezers are classified into —", "opts": ["Episodic wheeze and multitrigger wheeze", "Atopic and non-atopic wheeze", "Early and late wheeze", "Mild and severe wheeze"], "ans": 0, "exp": "Classification of patient: episodic wheeze; multitrigger wheeze (Book p122)", "type": "mcq"},
 {"id": "PEDS-C27-089", "sec": "Age < 5 yr (preschool)", "page": 122, "q": "Episodic wheeze in preschool children occurs during ___.", "opts": ["food ingestion alone", "viral infection", "exercise alone", "cold air alone"], "ans": 1, "exp": "Episodic wheeze: during viral infection (Book p122)", "type": "fill"},
