 {"id": "PEDS-C27-093", "sec": "Asthma probability", "page": 122, "q": "A preschool child needs more than ___ episodes before treatment for probable asthma.", "opts": ["6", "3", "1", "2"], "ans": 1, "exp": "> 3 episodes (along with symptoms lasting > 10 d after URI) (Book p122)", "type": "fill"},
 {"id": "PEDS-C27-094", "sec": "Age < 5 yr — treatment", "page": 122, "q": "Treatment of preschool asthma consists of —", "opts": ["Biological agents", "Oral steroids for 3 months", "Daily low-dose ICS therapy + reliever SABA", "Daily high dose ICS + LABA"], "ans": 2, "exp": "Controller: daily low-dose ICS therapy + reliever therapy: SABA (Book p122)", "type": "mcq"},
 {"id": "PEDS-C27-095", "sec": "Age < 5 yr — treatment", "page": 122, "q": "Preschool asthma therapy is reviewed after ___.", "opts": ["2 weeks", "6 months", "1 year", "2 months"], "ans": 3, "exp": "Review after 2 months (Book p122)", "type": "mcq"},
 {"id": "PEDS-C27-096", "sec": "Age < 5 yr — treatment", "page": 122, "q": "If there is improvement at the 2-month review of preschool asthma, the next step is to —", "opts": ["Stop treatment", "Start biological agents", "Add LABA", "Double the ICS dose"], "ans": 0, "exp": "Review after 2 months → improvement → stop treatment (Book p122)", "type": "mcq"},
 {"id": "PEDS-C27-097", "sec": "Age < 5 yr — treatment", "page": 122, "q": "If there is no improvement at review of a preschool asthmatic, you should —", "opts": ["Reassure and review after 6 months", "Treat as per age 6 to 11 guidelines", "Stop all treatment", "Start oral steroids lifelong"], "ans": 1, "exp": "No improvement → treat as per age 6 to 11 guidelines (Book p122)", "type": "mcq"},
 {"type": "case", "sec": "Age < 5 yr (preschool)", "page": 122, "stem": "A 3-year-old has had 4 episodes of wheeze in the past year. The most recent episode followed a viral URI and the cough and wheeze persisted for 12 days. He is otherwise well, with no features of chronic lung disease.", "q": "The appropriate management is —", "opts": ["Daily high dose ICS + LABA immediately", "Chest physiotherapy with antibiotics", "Daily low-dose ICS + reliever SABA, review after 2 months", "Inhaled salbutamol alone with review after 6 months"], "ans": 2, "exp": "> 3 episodes and symptoms lasting > 10 d after URI = ↑ probability of future asthma → controller daily low-dose ICS + reliever SABA, review after 2 months. (Book p122)", "id": "PEDS-C27-098"},
 {"type": "odd", "sec": "Age < 5 yr (preschool)", "page": 122, "q": "Odd one out (clinical pointers that raise the probability of future asthma in a preschooler):", "opts": ["Symptoms lasting > 10 days after a URI", "More than 3 episodes of wheeze", "Wheeze requiring treatment during viral illnesses", "Wheeze that resolves with antibiotics"], "ans": 3, "exp": "Persistence > 10 days after URI and > 3 episodes raise the probability of asthma and require treatment; response to ANTIBIOTICS suggests bacterial infection, not asthma. (Book p122)", "id": "PEDS-C27-099"},
